/// <summary>An end user's QuickBooks Desktop connection with its Web Connector installs and company file mismatches.</summary>
public sealed class EndUserConnection : global::DesktopAccountingApi.QuickBooksDesktop.ApiObject
{
    /// <summary>Unique identifier for the connection. Example: <c>"conn_01j9x4m6v4c8k2t7q0r5s3w1zc"</c>.</summary>
    [JsonPropertyName("id")]
    public string Id { get; set; } = null!;

    /// <summary>Always <c>integration_connection</c>.</summary>
    [JsonPropertyName("objectType")]
    public string ObjectType { get; set; } = null!;

    /// <summary>When the connection was created. UTC, ISO 8601 with milliseconds. Example: <c>"2026-10-05T16:03:59.002Z"</c>.</summary>
    [JsonPropertyName("createdAt")]
    public DateTimeOffset CreatedAt { get; set; }

    /// <summary>The integration this connection uses. Always <c>quickbooks_desktop</c>.</summary>
    [JsonPropertyName("integrationSlug")]
    public string IntegrationSlug { get; set; } = null!;

    /// <summary>Derived connection status. <c>pending_setup</c>: no Web Connector has finished setup. <c>online</c>: the Web Connector checked in recently and the last QuickBooks session opened. <c>quickbooks_unavailable</c>: the Web Connector checks in but QuickBooks could not be opened (<c>statusReason</c> holds the error code). <c>company_file_mismatch</c>: a different company file is open. <c>offline</c>: no recent check-in. <c>disabled</c>: turned off by the developer. Known values: <see cref="EndUserConnectionStatus"/>; other values may appear.</summary>
    [JsonPropertyName("status")]
    public string Status { get; set; } = null!;

    /// <summary>Code explaining a non-online status, when known: an error code (for example <c>QBD_ACCESS_NOT_GRANTED</c>), <c>QBD_QUICKBOOKS_NOT_RESPONDING</c> (the Web Connector checks in but QuickBooks does not answer, usually because a dialog is open) or <c>WEB_CONNECTOR_SCHEDULE_CHANGED</c>. With <c>online</c> it can be <c>QBD_FILE_MODE_CONFLICT</c>: QuickBooks reported a single-user/multi-user conflict and, for 2 minutes, the connection opens no session and synchronous requests fail fast with that code; or <c>WEB_CONNECTOR_SCHEDULE_CHANGED</c>. Example: <c>"QBD_QUICKBOOKS_NOT_RESPONDING"</c>.</summary>
    [JsonPropertyName("statusReason")]
    public string? StatusReason { get; set; }

    /// <summary>When the last request for this connection was made. UTC, ISO 8601.</summary>
    [JsonPropertyName("lastRequestAt")]
    public string? LastRequestAt { get; set; }

    /// <summary>When the last request succeeded. UTC, ISO 8601.</summary>
    [JsonPropertyName("lastSuccessfulRequestAt")]
    public string? LastSuccessfulRequestAt { get; set; }

    /// <summary>When the Web Connector last checked in. UTC, ISO 8601.</summary>
    [JsonPropertyName("lastHeartbeatAt")]
    public string? LastHeartbeatAt { get; set; }

    /// <summary>The connected company file, once a session has opened.</summary>
    [JsonPropertyName("companyFile")]
    public EndUserConnectionCompanyFile? CompanyFile { get; set; }

    /// <summary>Whether QuickBooks lets this connection read personal data (employee Social Security numbers, payroll details), as the Web Connector reported in the last verified session. <c>denied</c>: QuickBooks omits those fields, and employee responses carry a <c>QBD_PERSONAL_DATA_WITHHELD</c> warning for each one. <c>unknown</c>: no session has reported it yet. The QuickBooks Admin changes it under Edit &gt; Preferences &gt; Integrated Applications &gt; Company Preferences &gt; Properties; the new value shows after the next session. Known values: <see cref="EndUserConnectionPersonalDataAccess"/>; other values may appear. Example: <c>"allowed"</c>.</summary>
    [JsonPropertyName("personalDataAccess")]
    public string PersonalDataAccess { get; set; } = null!;

    /// <summary>Unique identifier for the end user. Example: <c>"eu_01j9x4m6v4c8k2t7q0r5s3w1zb"</c>.</summary>
    [JsonPropertyName("endUserId")]
    public string EndUserId { get; set; } = null!;

    /// <summary>Whether the connection is disabled. A disabled connection refuses Web Connector check-ins and fails new requests with <c>INTEGRATION_CONNECTION_DISABLED</c>.</summary>
    [JsonPropertyName("disabled")]
    public bool Disabled { get; set; }

    /// <summary>When the first Web Connector install finished setup, or null. UTC, ISO 8601 with milliseconds. Example: <c>"2026-10-05T16:03:59.002Z"</c>.</summary>
    [JsonPropertyName("setupCompletedAt")]
    public DateTimeOffset? SetupCompletedAt { get; set; }

    /// <summary>Web Connector installs (connector files) issued for this connection, newest first, at most 20.</summary>
    [JsonPropertyName("installs")]
    public IReadOnlyList<WebConnectorInstall> Installs { get; set; } = null!;

    /// <summary>Company file mismatches in the last 30 days. <c>total</c> is 0 when there were none.</summary>
    [JsonPropertyName("companyFileMismatches")]
    public EndUserConnectionCompanyFileMismatches CompanyFileMismatches { get; set; } = null!;
}

