/// <summary>The Error object.</summary>
public sealed class Error : global::DesktopAccountingApi.QuickBooksDesktop.ApiObject
{
    /// <summary>Error category. Use it to choose between retrying, fixing the request and asking the end user to act. Known values: <see cref="global::DesktopAccountingApi.QuickBooksDesktop.ErrorTypes"/>; other values may appear.</summary>
    [JsonPropertyName("type")]
    public string Type { get; set; } = null!;

    /// <summary>Stable error code from the error catalog. New codes may be added; a code's meaning never changes. Known values: <see cref="global::DesktopAccountingApi.QuickBooksDesktop.ErrorCodes"/>; other values may appear. Example: <c>"QBD_MODAL_DIALOG_OPEN"</c>.</summary>
    [JsonPropertyName("code")]
    public string Code { get; set; } = null!;

    /// <summary>Developer-facing explanation. May include IDs and field paths; never includes secrets.</summary>
    [JsonPropertyName("message")]
    public string Message { get; set; } = null!;

    /// <summary>A message that is safe to show to the end user.</summary>
    [JsonPropertyName("userFacingMessage")]
    public string UserFacingMessage { get; set; } = null!;

    /// <summary>HTTP status of the response. Every code defines one; on a request resource it is the status a synchronous call returns for the same error (for example 409 for <c>REQUEST_CANCELED</c>, 504 for <c>REQUEST_EXPIRED</c>). Nullable for compatibility only. Example: <c>503</c>.</summary>
    [JsonPropertyName("httpStatusCode")]
    public int? HttpStatusCode { get; set; }

    /// <summary>Native QuickBooks code when one exists: a qbXML statusCode (<c>"3200"</c>), an HRESULT (<c>"0x80040414"</c>) or a Web Connector code. Example: <c>"0x80040414"</c>.</summary>
    [JsonPropertyName("integrationCode")]
    public string? IntegrationCode { get; set; }

    /// <summary>The <c>Daapi-Request-Id</c> of this response. Include it when contacting support. Example: <c>"req_01j9x4m6v4c8k2t7q0r5s3w1zd"</c>.</summary>
    [JsonPropertyName("requestId")]
    public string RequestId { get; set; } = null!;

    /// <summary>Why this error happens.</summary>
    [JsonPropertyName("cause")]
    public string Cause { get; set; } = null!;

    /// <summary>Ordered actions that resolve the error, each with the responsible actor.</summary>
    [JsonPropertyName("fixes")]
    public IReadOnlyList<ErrorFix> Fixes { get; set; } = null!;

    /// <summary>Documentation section for this code. Example: <c>"https://www.desktopaccountingapi.com/docs/errors/#qbd_modal_dialog_open"</c>.</summary>
    [JsonPropertyName("docsUrl")]
    public string DocsUrl { get; set; } = null!;

    /// <summary>Repeating the identical request (with the same Idempotency-Key for writes) can succeed without changes. Also sent as the <c>Daapi-Should-Retry</c> header.</summary>
    [JsonPropertyName("retryable")]
    public bool Retryable { get; set; }

    /// <summary>Whether a write took effect: <c>applied</c> (QuickBooks confirmed it), <c>not_applied</c> (it certainly did not happen), <c>pending</c> (sent, still processing), <c>unknown</c> (sent, result could not be confirmed) or <c>not_applicable</c> (a read). Known values: <see cref="ErrorOutcome"/>; other values may appear.</summary>
    [JsonPropertyName("outcome")]
    public string Outcome { get; set; } = null!;

    /// <summary>Request field, query parameter or header the error refers to, when known. Example: <c>"companyName"</c>.</summary>
    [JsonPropertyName("param")]
    public string? Param { get; set; }

    /// <summary>Code-specific details, documented per code in the error catalog.</summary>
    [JsonPropertyName("details")]
    public IReadOnlyDictionary<string, JsonElement> Details { get; set; } = null!;
}

