    /// <summary>Shipping address for this estimate.</summary>
    [JsonPropertyName("shippingAddress")]
    public Address? ShippingAddress { get; set; }

    /// <summary>Whether this estimate is active. Inactive objects stay in QuickBooks but are hidden from most lists.</summary>
    [JsonPropertyName("isActive")]
    public bool? IsActive { get; set; }

    /// <summary>Purchase order number of this estimate.</summary>
    [JsonPropertyName("purchaseOrderNumber")]
    public string? PurchaseOrderNumber { get; set; }

    /// <summary>The terms for this estimate.</summary>
    [JsonPropertyName("terms")]
    public Reference? Terms { get; set; }

    /// <summary>Date payment of this estimate is due (YYYY-MM-DD). Example: <c>"2026-10-05"</c>.</summary>
    [JsonPropertyName("dueDate")]
    public DateOnly? DueDate { get; set; }

    /// <summary>The sales representative for this estimate.</summary>
    [JsonPropertyName("salesRepresentative")]
    public Reference? SalesRepresentative { get; set; }

    /// <summary>Shipment origin of this estimate.</summary>
    [JsonPropertyName("shipmentOrigin")]
    public string? ShipmentOrigin { get; set; }

    /// <summary>Total of all lines before sales tax, as a decimal string. Sent and received as a decimal string; scale is preserved. Example: <c>"1250.00"</c>.</summary>
    [JsonPropertyName("subtotal")]
    public decimal? Subtotal { get; set; }

    /// <summary>The sales tax item for this estimate.</summary>
    [JsonPropertyName("salesTaxItem")]
    public Reference? SalesTaxItem { get; set; }

    /// <summary>Sales tax rate applied, as a percentage. Percentage as a decimal string: "7.5" means 7.5 %. Sent and received as a decimal string; scale is preserved. Example: <c>"7.5"</c>.</summary>
    [JsonPropertyName("salesTaxPercentage")]
    public decimal? SalesTaxPercentage { get; set; }

    /// <summary>Total sales tax, as a decimal string. Sent and received as a decimal string; scale is preserved. Example: <c>"1250.00"</c>.</summary>
    [JsonPropertyName("salesTaxTotal")]
    public decimal? SalesTaxTotal { get; set; }

    /// <summary>Total amount of this estimate as a decimal string. Sent and received as a decimal string; scale is preserved. Example: <c>"1250.00"</c>.</summary>
    [JsonPropertyName("totalAmount")]
    public decimal? TotalAmount { get; set; }

    /// <summary>Currency of this estimate.</summary>
    [JsonPropertyName("currency")]
    public Reference? Currency { get; set; }

    /// <summary>Exchange rate from this estimate's currency to the home currency.</summary>
    [JsonPropertyName("exchangeRate")]
    public double? ExchangeRate { get; set; }

    /// <summary>Total amount in home currency of this estimate. Decimal string with up to 2 decimal places. Sent and received as a decimal string; scale is preserved. Example: <c>"1250.00"</c>.</summary>
    [JsonPropertyName("totalAmountInHomeCurrency")]
    public decimal? TotalAmountInHomeCurrency { get; set; }

    /// <summary>Internal memo for this estimate; shown in reports, not on printed forms.</summary>
    [JsonPropertyName("memo")]
    public string? Memo { get; set; }

    /// <summary>The customer message for this estimate.</summary>
    [JsonPropertyName("customerMessage")]
    public Reference? CustomerMessage { get; set; }

    /// <summary>Whether this estimate is in the queue of forms to email.</summary>
    [JsonPropertyName("isQueuedForEmail")]
    public bool? IsQueuedForEmail { get; set; }

    /// <summary>The sales tax code for this estimate.</summary>
    [JsonPropertyName("salesTaxCode")]
    public Reference? SalesTaxCode { get; set; }

    /// <summary>Built-in "Other" text field on this estimate.</summary>
    [JsonPropertyName("otherCustomField")]
    public string? OtherCustomField { get; set; }

    /// <summary>Your own UUID for this estimate, stored by QuickBooks so you can match records with your system.</summary>
    [JsonPropertyName("externalId")]
    public string? ExternalId { get; set; }

    /// <summary>Transactions linked to this estimate, such as payments applied to it.</summary>
